			return true, ora
		}
	}

	if r := exec(c, "ls /etc/almalinux-release", noSudo); r.isSuccess() {
		if r := exec(c, "cat /etc/almalinux-release", noSudo); r.isSuccess() {
			alma := newAlma(c)
